function TeamCard({ member }) {
  const ref = useRef(null)

  // Triggers, all from the real component:
  //   .in    — the card fades up when it first appears (every size)
  //   .open  — desktop keeps the original's 50%-visible appear trigger (and
  //            hover on top of it); the phone build opens a card on TAP
  //            instead, one at a time, which is how the real
  //            "Tab / Phone - Closed" variant behaves.
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const isPhone = () => window.matchMedia('(max-width: 809px)').matches

    const fadeIn = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('in')
            fadeIn.unobserve(entry.target)
          }
        })
      },
      { threshold: 0.35, rootMargin: '0px 0px -12% 0px' }
    )

    const open = new IntersectionObserver(
      (entries) => {
        if (isPhone()) return
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('open')
            open.unobserve(entry.target)
          }
        })
      },
      { threshold: 0.5 }
    )

    const onTap = () => {
      if (!isPhone()) return
      const wasOpen = el.classList.contains('open')
      document.querySelectorAll('.tm-card.open').forEach((o) => o.classList.remove('open'))
      if (!wasOpen) el.classList.add('open')
    }
    el.addEventListener('click', onTap)

    fadeIn.observe(el)
    open.observe(el)
    return () => {
      el.removeEventListener('click', onTap)
      fadeIn.disconnect()
      open.disconnect()
    }
  }, [])

  return (
    <article ref={ref} className="tm-card">
      {/* the photo layers sit in a wrapper that does NOT clip, so the opened
          portrait can spill out past the card the way the real one does */}
      <div className="tm-photo">
        <div className="tm-img tm-img-hover">
          <img src={member.photoHover} alt="" loading="lazy" />
        </div>
        <div className="tm-img tm-img-default">
          <img src={member.photo} alt={member.name} loading="lazy" />
        </div>
      </div>
      <div className="tm-content">
        <h3>{member.name}</h3>
        <p className="tm-role">{member.role}</p>
        {/* collapsed to height 0 until the card opens, exactly like the
            real component's own bio element */}
        <div className="tm-bio-wrap"><p className="tm-bio">{member.bio}</p></div>
      </div>
      {member.doodles.map((d) => DOODLES[d])}
    </article>
  )
}

